UPDATE public.member AS member
SET name = #{name},
	phone = #{phone}
WHERE member.id = #{memberId}
  AND EXISTS (
	SELECT 1
	FROM public.department_membership AS membership
	WHERE membership.department_id = #{departmentId}
	  AND membership.member_id = member.id
	  AND membership.ended_at IS NULL
  )

mapper.select:
SELECT id, member_id, joined_at
FROM public.department_membership
WHERE department_id = #{departmentId}
  AND member_id = #{memberId}
  AND ended_at IS NULL
FOR UPDATE

